    out=ROOT/'output/architecture-quality-001';exp=read(out/'experiment.json');seeds=exp['seeds'];final='after-r5'
    clean=Image.new('RGB',(2400,800),'#101923');overlay=Image.new('RGB',(2400,800),'#101923');beforeafter=Image.new('RGB',(2400,1600),'#101923')
